def solve_n_correct(n):
    target_count = n * (n - 1) // 2
    max_sum = 2 * target_count

    for k1 in range(-n*n, 2):
        k2 = 2 - k1
        if k2 <= k1: continue
        parity = k1 % 2

        def backtrack(current_ks, current_sums):
            if len(current_ks) == n:
                return current_ks

            last_k = current_ks[-1]
            upper_bound = max_sum - current_ks[-1]

            for k in range(last_k + 2, upper_bound + 1, 2):
                new_sums = set()
                possible = True
                for i in range(len(current_ks)):
                    s = k + current_ks[i]
                    if s < 2 or s > max_sum or s in current_sums or s in new_sums:
                        possible = False
                        break
                    new_sums.add(s)

                if possible:
                    res = backtrack(current_ks + [k], current_sums | new_sums)
                    if res: return res
            return None

        res = backtrack([k1, k2], {2})
        if res:
            print(f"n={n} works with k={res}")
            return True
    return False

